// The card for one request at one step: what Landledger shows (the request and its evidence), the evidence hash it was
// built from, and the buttons. Approve carries ll1|request|step|hash; Landledger reads it from the signed press.
// Only the budget owner's step is decided in Slack; Finance and CFO steps are decided in Landledger.
function card(detail, step, url, relayable, notice) {
  const r = detail.request;
  const e = detail.evidence ?? {};
  const sha = String(detail.evidenceSha256 ?? '');
  const money = (v) => (v === null || v === undefined ? '—' : `$${Number(v).toLocaleString('en-US', { maximumFractionDigits: 2 })}`);
  const per = r.recurrence === 'monthly' ? ' a month' : '';
  const lines = (r.evidence?.lines ?? []).map((l) => `• ${l.label}: ${money(l.amount)}`).join('\n');
  const links = [...(r.evidence?.links ?? []), ...(r.related ?? []).filter((x) => x.url).map((x) => ({ label: x.type === 'pull_request' ? 'Pull request' : x.type, url: x.url }))]
    .map((l) => `<${l.url}|${l.label}>`).join(' · ');
  const who = r.requester?.kind === 'agent' ? `${r.requester.agent.name} (agent), sponsor ${r.requester.sponsor?.name ?? r.requester.sponsor?.email}` : r.requester?.person?.name ?? r.requester?.person?.email;
  const text = `${r.number}: ${r.title} — ${money(r.amount.amount)}${per} for ${r.costCenter.code}`;
  const open = { type: 'button', action_id: 'landledger_open', text: { type: 'plain_text', text: 'Open in Landledger' }, url };
  const buttons = relayable
    ? [
        { type: 'button', action_id: 'landledger.approve', style: 'primary', text: { type: 'plain_text', text: 'Approve' }, value: `ll1|${r.id}|${step.position}|${sha}` },
        { type: 'button', action_id: 'landledger_reject', style: 'danger', text: { type: 'plain_text', text: 'Reject in Landledger' }, url },
        open,
      ]
    : [open];
  const blocks = [
    ...(notice ? [{ type: 'context', block_id: 'landledger_notice', elements: [{ type: 'mrkdwn', text: notice }] }] : []),
    { type: 'header', text: { type: 'plain_text', text: `${r.number} · ${r.title}`.slice(0, 150) } },
    { type: 'section', fields: [
      { type: 'mrkdwn', text: `*Amount*\n${money(r.amount.amount)}${per}` },
      { type: 'mrkdwn', text: `*Cost center*\n${r.costCenter.code} · ${r.costCenter.name}` },
      { type: 'mrkdwn', text: `*Asked by*\n${who}` },
      { type: 'mrkdwn', text: `*Step*\n${step.label}${step.deadlineAt ? ` (by ${String(step.deadlineAt).slice(0, 10)})` : ''}` },
    ] },
    ...(r.note ? [{ type: 'section', text: { type: 'mrkdwn', text: `> ${r.note.slice(0, 2900)}` } }] : []),
    { type: 'section', text: { type: 'mrkdwn', text: [
      `*The month for ${r.costCenter.code}* (${e.month ?? ''}): spent ${money(e.actual)}, reserved ${money(e.reserved)}, budget ${money(e.budget)}; left after this ${money(e.leftAfter)}.`,
      e.why ? `_${e.why}_` : '', lines, r.evidence?.basis ?? '', links,
    ].filter(Boolean).join('\n').slice(0, 2990) } },
    { type: 'context', elements: [{ type: 'mrkdwn', text: `Evidence ${sha.slice(0, 12)}… · ${relayable ? 'Approve here for the budget owner\'s step; reject with a reason in Landledger.' : 'This step is decided in Landledger, not Slack.'} Finance and CFO steps are decided in Landledger, not Slack.` }] },
    { type: 'actions', block_id: 'landledger_decision', elements: buttons },
  ];
  return { text, blocks, sha };
}

// One card per approver of the pending step who has an email.
const event = $('Step waits on approvers').first().json;
const detail = $input.first().json;
const relayable = event.relayable === true;
const built = card(detail, event.step, event.url, relayable, '');
return (event.approvers ?? []).filter((a) => a.email).map((a) => ({
  email: a.email, name: a.name, text: built.text, blocks: built.blocks,
  requestId: detail.request.id, step: event.step.position, sha: built.sha, url: event.url,
}));

