// Settings: the Slack workspace and app whose presses this flow relays (Landledger checks them again).
const SLACK_TEAM_ID = '';  // T…, the workspace's team id
const SLACK_APP_ID = '';   // A…, the Slack app's id (Basic Information)

// A press worth relaying: from our workspace and app, Approve on a Landledger card, with the signed request kept.
const m = /^ll1\|(req_[\w-]{1,80})\|(\d{1,2})\|([0-9a-f]{64})$/.exec(String($json.value ?? ''));
let why = '';
if (!SLACK_TEAM_ID || !SLACK_APP_ID) why = 'Set SLACK_TEAM_ID and SLACK_APP_ID in Check the press';
else if ($json.teamId !== SLACK_TEAM_ID || $json.apiAppId !== SLACK_APP_ID) why = `a press from another Slack team or app (${$json.teamId}, ${$json.apiAppId})`;
else if ($json.actionId !== 'landledger.approve') why = `not Approve (${$json.actionId})`;
else if (!m) why = 'the button value is not a Landledger card';
else if (!$json.rawBody || !$json.headers?.['x-slack-signature']) why = 'the press came without its signed body';
else if ($json.userTeamId && $json.userTeamId !== SLACK_TEAM_ID) why = 'pressed by someone from another organization';
return {
  ok: !why, why, teamId: SLACK_TEAM_ID,
  requestId: m?.[1] ?? null, step: m ? Number(m[2]) : null, sha: m?.[3] ?? null,
  channel: $json.channel, ts: $json.messageTs, user: $json.user,
};

// Relay only a press on a card this flow sent (the button matches the recorded card), by a full member of the workspace:
// not a guest, not from another organization (Slack Connect), not deactivated, not a bot.
const press = $('Check the press').item.json;
const sent = $('Find the card').item.json;
const user = $json;
let why = '';
if (sent.request_id !== press.requestId || Number(sent.step) !== press.step || sent.evidence_sha256 !== press.sha) why = 'the button does not match the card this flow sent';
else if (user.deleted) why = `${user.name ?? user.id} is deactivated in Slack`;
else if (user.is_guest || user.is_restricted || user.is_ultra_restricted) why = `${user.name ?? user.id} is a guest in this workspace`;
else if (user.is_stranger || (user.team_id && user.team_id !== press.teamId)) why = `${user.name ?? user.id} is from another organization`;
else if (user.is_bot || user.is_app_user) why = 'a bot pressed it';
return { ok: !why, why, user: user.id, name: user.real_name ?? user.name ?? null };

// The card's new state: the decision Landledger recorded, or why not. Landledger down or unreachable: the buttons stay with
// "Try again". Refused: why, with Open in Landledger. A stale card (409): it is rebuilt from Landledger now.
const press = $('Button pressed').item.json;
const check = $('Check the press').item.json;
const original = press.raw?.message?.blocks ?? [];
const openUrl = original.flatMap((b) => b.elements ?? []).find((el) => el.action_id === 'landledger_open')?.url ?? '';
const open = { type: 'actions', block_id: 'landledger_decision', elements: [{ type: 'button', action_id: 'landledger_open', text: { type: 'plain_text', text: 'Open in Landledger' }, url: openUrl }] };
const failed = $json.error ? String($json.error.message ?? $json.error) : '';
const status = Number((/Landledger API error (\d{3})/.exec(failed) ?? [])[1] ?? 0);
const number = press.raw?.message?.text?.split(':')[0] ?? check.requestId;
const section = (text) => ({ type: 'section', text: { type: 'mrkdwn', text } });
if (!failed) {
  const d = $json.decision;
  const text = `✅ ${$json.request.number} ${d.outcome === 'approve' ? 'approved' : 'rejected'} by ${d.person.name} · ${$json.request.title}`;
  return { text, blocks: [section(text), open], refresh: false };
}
if (!status || status >= 500 || status === 429) {
  const text = `⚠️ ${number}: Landledger did not answer (${failed.slice(0, 200)}). Try again.`;
  const kept = original.filter((b) => b.block_id !== 'landledger_notice');
  return { text: press.raw?.message?.text ?? text, blocks: [{ type: 'context', block_id: 'landledger_notice', elements: [{ type: 'mrkdwn', text }] }, ...kept], refresh: false };
}
if (status === 409) return { text: '', blocks: [], refresh: true, openUrl };
const text = `⚠️ ${number}: Landledger did not take your answer: ${failed.replace(/^Landledger API error \d{3}: /, '')}`;
return { text, blocks: [section(text), open], refresh: false };

