// A stale card (the request changed, or the card is older than Landledger's 30 minutes): rebuilt from what Landledger
// shows now, with the new evidence hash, and the person presses again.
const check = $('Check the press').item.json;
const said = $('Say what happened').item.json;
const detail = $json;
const step = (detail.request.steps ?? []).find((s) => s.position === check.step) ?? { position: check.step, label: `Step ${check.step}` };
const relayable = detail.request.status === 'pending' && step.key === 'budget_owner' && ['infra_change', 'ai_budget', 'tool_or_seat', 'other'].includes(detail.request.kind);
const built = card(detail, step, said.openUrl, relayable, '⚠️ The request changed or this card was older than 30 minutes: here it is as Landledger shows it now. Press again.');
return { text: built.text, blocks: built.blocks, sha: built.sha };
